import React from "react";
import styled from "styled-components";
import { Facebook, Twitter, Linkedin } from "lucide-react";

const FooterContainer = styled.footer`
  background-color: #f0f0f0;
  padding: 50px 30px 30px 30px;
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  border-top: 1px solid #ddd;
  position: relative;
`;

const Column = styled.div`
  flex: 1;
  min-width: 200px;
  margin: 10px 20px;

  h4 {
    font-size: 18px;
    margin-bottom: 20px;
    color: #333;
  }

  ul {
    list-style: none;
    padding: 0;

    li {
      margin-bottom: 12px;
      font-size: 15px;
      color: #666;
      cursor: pointer;

      &:hover {
        color: #000;
      }
    }
  }
`;

const SocialIcons = styled.div`
  display: flex;
  gap: 16px;
  margin-top: 10px;

  svg {
    color: #444;
    transition: all 0.3s;
    cursor: pointer;

    &:hover {
      color: #000;
      transform: scale(1.1);
    }
  }
`;

const Copyright = styled.div`
  width: 100%;
  text-align: center;
  margin-top: 40px;
  font-size: 14px;
  color: #999;
  border-top: 1px solid #ccc;
  padding-top: 20px;
`;

const Footer = () => {
  return (
    <FooterContainer>
      <Column>
        <h4>Về chúng tôi</h4>
        <ul>
          <li>Giới thiệu</li>
          <li>Liên hệ</li>
          <li>Blog</li>
        </ul>
      </Column>

      <Column>
        <h4>Hỗ trợ</h4>
        <ul>
          <li>Câu hỏi thường gặp</li>
          <li>Chính sách bảo mật</li>
          <li>Điều khoản dịch vụ</li>
        </ul>
      </Column>

      <Column>
        <h4>Kết nối</h4>
        <SocialIcons>
          <Facebook size={24} />
          <Twitter size={24} />
          <Linkedin size={24} />
        </SocialIcons>
      </Column>

      <Copyright>© 2025 YourCompany. All rights reserved.</Copyright>
    </FooterContainer>
  );
};

export default Footer;
